DROP TRIGGER rm_workspace_auth_telemetry_events_no_update;
DROP TRIGGER rm_workspace_auth_telemetry_events_no_delete;
ALTER TABLE rm_workspace_auth_telemetry_events RENAME TO rm_workspace_auth_telemetry_events_v6;
CREATE TABLE rm_workspace_auth_telemetry_events (
 id INTEGER PRIMARY KEY, endpoint TEXT NOT NULL CHECK(endpoint IN ('sign-in-email','send-verification-email','verify-email','request-password-reset','reset-password','sign-out','revoke-session','revoke-other-sessions','two-factor-enable','two-factor-verify','two-factor-verify-backup-code')), outcome TEXT NOT NULL CHECK(outcome IN ('attempted','accepted','rejected','unknown')), user_id TEXT REFERENCES "user"(id), session_id TEXT, identity_hash TEXT CHECK(identity_hash IS NULL OR length(identity_hash)=64), identity_key_version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
INSERT INTO rm_workspace_auth_telemetry_events (id, endpoint, outcome, user_id, session_id, identity_hash, identity_key_version, created_at) SELECT id, endpoint, outcome, user_id, session_id, identity_hash, identity_key_version, created_at FROM rm_workspace_auth_telemetry_events_v6 ORDER BY id;
DROP TABLE rm_workspace_auth_telemetry_events_v6;
CREATE TRIGGER rm_workspace_auth_telemetry_events_no_update BEFORE UPDATE ON rm_workspace_auth_telemetry_events BEGIN SELECT RAISE(ABORT, 'workspace auth telemetry events are append-only'); END;
CREATE TRIGGER rm_workspace_auth_telemetry_events_no_delete BEFORE DELETE ON rm_workspace_auth_telemetry_events BEGIN SELECT RAISE(ABORT, 'workspace auth telemetry events are append-only'); END;
